/bin/bash -lc "python3 -c 'from pathlib import Path; import re; root=Path.cwd(); seen=set(); active=set(); target=\"MIPStarRE.QPBT.Extraction.RegisterTransport\"
def visit(module):
 if module in active: raise SystemExit(\"Import cycle at \"+module)
 if module in seen: return
 active.add(module)
 path=root.joinpath(*module.split(\".\")).with_suffix(\".lean\")
 if path.is_file():
  for dep in re.findall(r\""'^import'"\\s+(\\S+)\",path.read_text(),re.M):
   if dep.startswith(\"MIPStarRE.\"): visit(dep)
 active.remove(module); seen.add(module)
visit(target); print(\"Acyclic project import closure:\",len(seen),\"modules\")'"

